+func signLinkState(userId string, now time.Time) (string, error) {
+	if userId == "" || len(auth.Secret) == 0 {
+		return "", errors.New("link state unavailable")
+	}
+	payload, err := json.Marshal(linkState{UserID: userId, Expires: now.Add(10 * time.Minute).Unix()})
+	if err != nil {
+		return "", err
+	}
+	encoded := base64.RawURLEncoding.EncodeToString(payload)
+	mac := hmac.New(sha256.New, auth.Secret)
+	_, _ = mac.Write([]byte(encoded))
+	return encoded + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil)), nil
