+func verifyLinkState(state string, now time.Time) (string, error) {
+	parts := strings.Split(state, ".")
+	if len(parts) != 2 || len(auth.Secret) == 0 {
+		return "", errors.New("invalid link state")
+	}
+	signature, err := base64.RawURLEncoding.DecodeString(parts[1])
+	if err != nil {
+		return "", err
+	}
+	mac := hmac.New(sha256.New, auth.Secret)
+	_, _ = mac.Write([]byte(parts[0]))
+	if !hmac.Equal(signature, mac.Sum(nil)) {
+		return "", errors.New("invalid link state signature")
+	}
+	payload, err := base64.RawURLEncoding.DecodeString(parts[0])
+	if err != nil {
+		return "", err
+	}
+	var data linkState
+	if err := json.Unmarshal(payload, &data); err != nil {
+		return "", err
+	}
+	if data.UserID == "" || now.Unix() >= data.Expires {
+		return "", errors.New("expired link state")
+	}
+	return data.UserID, nil
+}
